INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('seed-choc-mousse', 'Chocolate Mousse Bulking Shake', 'smoothie', 'Thick and mousse-like. Eat it with a spoon, or thin it out to drink.', '["breakfast","lunch"]'::jsonb, 1, 1070, 73, NULL, NULL, '["80 g rolled oats","300 g Fairlife chocolate milk","2 scoops chocolate protein powder","32 g almond butter","50 g pitted dates, chopped","1 handful of ice","2 tbsp water, to thin (optional)"]'::jsonb, '["Add the oats, chocolate milk, protein powder, almond butter and dates to a blender.","Blend about 1 minute, until it is thick like a chocolate mousse.","To drink it rather than spoon it, add the ice and the water.","Blend about 1 minute more, until smooth."]'::jsonb, '', 0) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('seed-rice-krispie', 'Rice Krispie Treat Bulking Shake', 'smoothie', 'Tastes like a Rice Krispie treat in shake form.', '["breakfast","lunch"]'::jsonb, 1, 1068, 77, NULL, NULL, '["80 g rolled oats","300 g fat-free Fairlife milk","2 scoops vanilla protein powder","32 g peanut butter","150 g banana","20 g honey","15 g Rice Krispies, for the top"]'::jsonb, '["Add everything except the Rice Krispies to a blender.","Blend about 1 minute, until smooth.","Pour into a glass and scatter the Rice Krispies on top for the crunch."]'::jsonb, '', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('seed-berry-fresh', 'Berry Fresh Special Bulking Shake', 'smoothie', 'The highest-protein of all of these.', '["breakfast","lunch"]'::jsonb, 1, 1032, 87, NULL, NULL, '["80 g rolled oats","300 g fat-free Fairlife milk","2 scoops strawberry protein powder","150 g Greek yogurt","32 g peanut butter","150 g frozen mixed berries","20 g honey"]'::jsonb, '["Add everything to a blender.","Blend about 1 minute, to a smoothie texture, and drink."]'::jsonb, '', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('seed-choc-pb', 'Chocolate Peanut Butter Shake', 'smoothie', 'Tastes like a peanut butter cup milkshake.', '["breakfast","lunch"]'::jsonb, 1, 1110, 73, 115, 40, '["2 cups whole milk","1.5 scoops chocolate protein powder","1 large banana (frozen works well)","1/2 cup oats","3 tbsp natural peanut butter","2 tbsp cocoa powder","1 tbsp honey","1/3 tsp vanilla extract","1 handful of ice"]'::jsonb, '["Add the milk, protein powder, banana and oats to the blender.","Add the peanut butter, cocoa powder, honey and vanilla.","Add the ice and blend until smooth."]'::jsonb, '', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('seed-green-machine', 'Green Machine Shake', 'smoothie', 'The spinach disappears completely under the mango and banana.', '["breakfast","lunch"]'::jsonb, 1, 1080, 65, 120, 35, '["2 cups whole milk","2 cups packed baby spinach","1 scoop vanilla protein powder","1/2 cup Greek yogurt","1 large banana","1 cup frozen mango","1/2 cup oats","1/4 avocado","2 tbsp ground flaxseed","1 tbsp honey"]'::jsonb, '["Blend the milk and spinach on their own for about 20 seconds, until no green flecks are left.","Add the protein powder, yogurt, banana, mango, oats, avocado, flaxseed and honey.","Blend until smooth."]'::jsonb, '', 4) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('seed-tropical-gainer', 'Tropical Gainer Shake', 'smoothie', 'The lightest and lowest-fat of these. Good straight after training.', '["breakfast","lunch"]'::jsonb, 1, 680, 46, 95, 15, '["1.5 cups coconut milk (from a carton)","1 scoop vanilla protein powder","1/2 cup Greek yogurt","1 cup frozen mango","1 cup frozen pineapple","1/2 cup oats","2 tbsp unsweetened shredded coconut","1 tbsp ground flaxseed","1 handful of ice"]'::jsonb, '["Add the coconut milk, protein powder and Greek yogurt to the blender.","Add the mango, pineapple, oats, shredded coconut and flaxseed.","Add the ice and blend until smooth."]'::jsonb, '', 5) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-queso-chicken-mac-n-cheese', 'Queso Chicken Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 600, 48, 65, 20, '["900g (32oz) chicken breast","120g red enchilada sauce","80g (3 Tbsp) green chiles","400g (14oz) can of fire-roasted tomatoes","2 Tbsp garlic purée","2 tsp onion powder","1 Tbsp salt","1 tsp black pepper","tsp cayenne (amount unclear in the source)","672g (24 oz) whole grain pasta 1","Chopped cilantro","800g full-fat cottage cheese","120g full-fat cream cheese","200g extra sharp cheddar cheese","40g cheddar powder","120g red enchilada sauce","180g whole milk","2 orange bell peppers","2 red bell peppers","1 onion","1 Tbsp olive oil"]'::jsonb, '["Preheat oven to 400F (200C). Dice bell peppers and onion, toss with olive oil, spread on a baking sheet, and roast for 20-25 minutes until softened and lightly browned.","Prepare the Chicken: Dice the chicken breast and add to the slow cooker with red enchilada sauce, green chiles, fire-roasted tomatoes, garlic purée, onion powder, salt, black pepper, and cayenne. Stir to coat. Add roasted vegetables. Cover and cook on high for 2-3 hours or low for 3-4 hours until tender.","Cook the Pasta: Bring a pot of salted water to a boil, add whole grain pasta, cook halfway, then drain and mix in butter to prevent sticking and boost calories. Prepare the High-Calorie Queso Sauce: Shred the cheddar cheese and blend with full-fat cottage cheese, full-fat cream cheese, cheddar powder, red enchilada sauce, and whole milk until smooth. Combine & Finish: Once the chicken is cooked, shred slightly in the slow cooker. Add half-cooked pasta and queso sauce, stirring to coat. Cover and cook on low for 15- 20 minutes until sauce thickens and pasta is tender. Serve & Store: Divide into 10 servings, garnish with chopped cilantro, and let leftovers cool before freezing."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add extra shredded cheese for a richer taste or hot sauce for extra heat!', 6) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-peanut-miso-chicken-rice-bowls', 'Peanut Miso Chicken Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 7, 700, 55, 75, 22, '["1340g (48oz) boneless, skinless chicken thighs","160g peanut butter","60g (4 Tbsp) white miso paste","60g (4 Tbsp) soy sauce","50g (3 Tbsp) maple syrup","30g (2 Tbsp) rice vinegar","20g (4 tsp) ginger purée","20g (4 tsp) garlic purée","Red chili flakes, black pepper & sesame seeds to taste","Splash of bone broth or water","480g (2 cups) short grain rice","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)","Chopped green onions","Toasted sesame seeds"]'::jsonb, '["Prepare the Peanut Miso Sauce: In a bowl, combine peanut butter, white miso paste, soy sauce, maple syrup, rice vinegar, ginger purée, garlic purée, red chili flakes, black pepper, and sesame seeds. Mix until a smooth paste forms.","Slow Cook the Chicken: Add chicken thighs to the slow cooker. Pour in half of the peanut miso sauce and a splash of chicken bone broth or water to thin slightly. Mix to coat the chicken evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours until tender and fully cooked.","Cook the Rice: In a medium saucepan, bring chicken bone broth and butter to a boil. Stir in short grain rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off heat and let sit, covered, for 10 minutes before fluffing with a fork.","Finish the Chicken: Once the chicken is fully cooked, add the remaining peanut miso sauce and stir thoroughly to coat the chicken in the rich, flavorful sauce. Assemble & Serve: Divide the rice and chicken into 7 meal prep containers (15 ounces (425g) per serving.) Garnish with chopped green onions and toasted sesame seeds. Let cool before storing."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Try adding crushed peanuts for extra crunch or a drizzle of sriracha for spice!', 7) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-pineapple-teriyaki-pulled-pork-rice-bowls', 'Pineapple Teriyaki Pulled Pork Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 700, 50, 70, 22, '["Pork","1790g (64oz) Pork loin 1 Pineapple (400g), diced","100g soy sauce","90g (6 Tbsp) mirin","100g (5 Tbsp) honey","2 Tbsp grated ginger","2 Tbsp grated garlic 1","4 Tbsp cornstarch","4 Tbsp cold water","120g full-fat mayo","120g full-fat Greek yogurt","30g ketchup","70g sriracha","Salt, pepper, garlic powder to taste Whole milk, as needed for consistency","1 Tbsp melted butter","2 stalks green onions, chopped","600g (3 cups) short grain or sushi rice","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)"]'::jsonb, '["Prepare the Pork: Cut the pork loin into four large pieces and place them in the slow cooker. Dice the pineapple, grate the ginger & garlic, and add soy sauce, mirin, honey, and sesame oil to the slow cooker. Stir to coat evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours until the pork is tender and easily shredded. Shred the Pork & Thicken Sauce: Once cooked, shred the pork in the slow cooker using two forks. Mix cornstarch with cold water to create a slurry, then gradually stir into the slow cooker until the sauce thickens to your desired consistency.","Cook the Rice: Bring chicken bone broth and butter to a boil in a medium saucepan. Stir in short grain rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the heat and let sit, covered, for 10 minutes before fluffing with a fork. Make the High-Calorie Yum Yum Sauce: In a bowl, whisk together full-fat mayo, full-fat Greek yogurt, ketchup, sriracha, salt, pepper, garlic powder, and melted butter. Add whole milk as needed to reach the desired consistency. Assemble & Serve: Divide the rice and pulled pork into 10 meal prep containers (~16oz per serving). Drizzle with Yum Yum sauce and garnish with chopped green onions. Let cool before storing."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add crushed cashews or sesame seeds for extra crunch & healthy fats!', 8) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-green-enchilada-chicken-rice-soup', 'Green Enchilada Chicken & Rice Soup', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 550, 50, 50, 15, '["Chicken","1790g (64oz) diced boneless, skinless chicken thighs","500g (2 cups) chicken bone broth","420g green enchilada sauce","226g (8oz) Hatch green chiles","1 white onion, diced","Juice of","1 lime","1 Tbsp salt","1 Tbsp garlic powder","Dash of black pepper 1","400g (2 cups) jasmine rice","1 Tbsp butter","750g (3 cups) chicken bone broth","60g (3 Tbsp) honey","350g full-fat Greek yogurt","1 bunch cilantro, chopped","1 ripe avocado, mashed"]'::jsonb, '["Slow Cook the Chicken: Add chicken thighs, green enchilada sauce, Hatch green chiles, diced white onion, lime juice, salt, garlic powder, black pepper, and olive oil to the slow cooker. Stir everything together to coat the chicken evenly. Cover and cook on high for 2-3 hours or low for 4-5 hours until the chicken is tender and fully cooked.","Cook the Rice: Bring chicken bone broth and butter to a boil in a medium saucepan. Stir in jasmine rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the eat and let sit, covered, for 10 minutes before fluffing with a fork. Shred the Chicken & Combine: Shred the chicken directly in the slow cooker, mixing it into the flavorful sauce once the chicken is fully cooked. Add in cooked jasmine rice and bone broth mixture (the broth should be mostly absorbed into the rice). Finish & Thicken: Stir in honey, chopped cilantro, full-fat Greek yogurt, and mashed avocado. Cover and let sit for 20-30 minutes to allow flavors to meld. Serve & Store: Divide the mixture into 10 meal prep containers (~16oz per serving) and let it cool before storing it in the fridge or freezer."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add extra avocado slices or shredded cheese for added richness.', 9) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-frozen-cheesy-chicken-rice-burritos', 'Frozen Cheesy Chicken & Rice Burritos', 'meal', '', '["lunch","dinner"]'::jsonb, 18, 525, 38, 60, 15, '["Chicken","1340g (48oz) boneless skinless chicken thighs","2 packets of taco seasoning","15g (1 Tbsp) lime juice","15g (1 Tbsp) chicken bouillon","420g (15oz) green enchilada sauce","Garlic powder and salt, to taste","1 Tbsp olive oil","5 Roma tomatoes, diced","3 jalapeños, diced (remove seeds for less spice)","2 white onions, diced","1 bunch cilantro, chopped","Juice of","2 limes","Pinch of salt 1","500g (2 cups) jasmine rice","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)","500g full-fat Greek yogurt","180g sharp cheddar cheese","150g whole milk mozzarella cheese 2","18 burrito-sized flour tortillas"]'::jsonb, '["Slow Cook the Chicken: Place chicken thighs into the slow cooker. Add taco seasoning, lime juice, chicken bouillon, green enchilada sauce, garlic powder, salt, and olive oil. Stir to coat evenly. Cover and cook on high for 2–3 hours or low for 3–4 hours until the chicken is tender and easy to shred.","Shred the Chicken: Once cooked, shred the chicken directly in the slow cooker with two forks, mixing it into the flavorful sauce.","Cook the Rice: Bring chicken bone broth and butter to a boil in a medium saucepan. Stir in jasmine rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the heat and let sit, covered, for 10 minutes before fluffing with a fork.","Prepare the Pico de Gallo: In a bowl, mix diced tomatoes, jalapeños, onions, cilantro, lime juice, salt, and olive oil. Stir and set aside.","Combine the Filling: Mix the rice into the slow cooker with the shredded chicken once the rice is cooked. Stir in Greek yogurt, sharp cheddar, mozzarella cheese, cream cheese, and prepared pico de gallo. Stir thoroughly until all ingredients are evenly mixed and the cheese has melted. Let cool slightly to thicken.","Assemble the Burritos: Lay out one tortilla, spoon a portion of the chicken and rice mixture onto it, and roll tightly, folding in the sides. Repeat with the remaining tortillas.","Freeze for Later: Wrap each burrito individually in foil or plastic wrap, then store it in a freezer-safe bag or container for easy meal prep."]'::jsonb, 'For meal prep: Store burritos in the freezer for up to 3 months. Reheating (Microwave): Remove foil, wrap in a damp paper towel, and heat for 2-3 minutes, flipping halfway. Optional add-ins: Add avocado slices, extra cheese, or sour cream before eating for even more calories & creaminess!', 10) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-sundried-tomato-spinach-feta-pasta', 'Sundried Tomato Spinach Feta Pasta', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 700, 55, 70, 22, '["Chicken","1340g (48oz) boneless, skinless chicken thighs","45g (3 Tbsp) balsamic vinegar","150g sundried tomatoes, chopped 7–8 cloves garlic, minced","1 Tbsp salt","2 tsp onion powder","2 tsp black pepper","Red chili flakes, to taste","1 Tbsp olive oil","250g (8 cups) spinach, chopped","15 basil leaves, chopped","400g (2 cups) feta cheese, crumbled","30g (2 Tbsp) pesto","600g (2 cups) full-fat cottage cheese","360g whole milk 2","750g bow tie pasta","360g pasta water for slow cooker"]'::jsonb, '["Prepare the Chicken: Mince the garlic and chop the sundried tomatoes. In a bowl, mix them with balsamic vinegar, onion powder, black pepper, salt, red chili flakes, and olive oil. Place the chicken thighs in the slow cooker and pour the mixture over them, ensuring an even coating. Cover and cook on high for 3–4 hours or low for 4–5 hours until the chicken is tender.","Blanch the Greens: While the chicken cooks, cut the spinach & basil into bite-sized pieces. Blanch them in boiling water for 1 minute, then transfer to an ice bath, drain, and set aside. Shred & Mix: Once the chicken is cooked, shred it directly in the slow cooker. Add the blanched spinach, basil, feta cheese, and pesto, stirring well to combine. Cover and cook on high while prepping the sauce and pasta.","Prepare the Cheese Sauce: Blend full-fat cottage cheese, whole milk, and butter until smooth.","Cook the Pasta: Bring a large pot of salted water to a boil. Add bow-tie pasta and cook until halfway done according to package instructionsreserve 1.5 cups of pasta water before draining.","Combine Everything: In the slow cooker, stir in the partially cooked pasta, reserved pasta water, and cheese sauce, mixing thoroughly. Cover and cook on high for 15 minutes or until the pasta is fully cooked and the sauce thickens. Rest & Serve: Let the dish rest for a few minutes to allow the flavors to meld. Divide into 10 meal prep containers (~16oz per serving). Let cool completely before storing in freezer- safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with grated Parmesan, toasted pine nuts, or extra feta for added flavor & calories!', 11) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-garlic-butter-chicken-alfredo', 'Garlic Butter Chicken Alfredo', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 650, 52, 68, 22, '["900g (32oz) chicken breast, diced","45g Parmigiano Reggiano, grated","Juice of","1 lemon","2 Tbsp garlic purée","2 tsp garlic powder","2 tsp onion powder","1 Tbsp salt","1 tsp black pepper","2 tsp Kinder Roasted Garlic Brown Butter Seasoning","Dash of crushed red pepper","120g chicken bone broth","45g (3 Tbsp) butter","800g full-fat cottage cheese","180g full-fat cream cheese","150g Parmigiano Reggiano, grated","240g (1 cup) whole milk 2","750g pasta of choice","180g pasta water (reserved from boiling pasta)"]'::jsonb, '["Prepare the Garlic Chicken: Add diced chicken, Parmigiano Reggiano, lemon juice, garlic purée, garlic powder, onion powder, salt, black pepper, crushed red pepper, Kinder Roasted Garlic Brown Butter seasoning, and chicken bone broth to the slow cooker. Stir to coat evenly, then place butter on top. Cover and cook on high for 2-3 hours or low for 4-5 hours until the chicken is tender and shreds easily.","Make the Alfredo Sauce: While the chicken cooks, blend full-fat cottage cheese, full-fat cream cheese, Parmigiano Reggiano, whole milk, and butter until smooth and creamy.","Cook the Pasta: Bring a pot of salted water to a boil, cook pasta for half the time listed on the package, then drain, reserving cup of pasta water.","Combine Everything: Shred the cooked chicken directly in the slow cooker. Stir in half-cooked pasta, reserved pasta water, and the blended Alfredo sauce. Cover and cook on low for 15-20 minutes, allowing the sauce to thicken and the pasta to finish cooking until tender. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with extra grated Parmigiano or crispy pancetta for more flavor & richness.', 12) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chili-garlic-chicken-fried-rice', 'Chili Garlic Chicken Fried Rice', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 700, 50, 80, 24, '["1360g (48oz) chicken thighs","75g (5 Tbsp) chili garlic sauce","45g (3 Tbsp) soy sauce","75g (4 Tbsp) honey","1 Tbsp rice vinegar","1 Tbsp minced ginger","Salt & pepper, to taste","1 Tbsp sesame oil","180g full-fat Greek yogurt","60g (4 Tbsp) mayo","45g (3 Tbsp) gochujang","45g (3 Tbsp) sriracha","Splash of rice vinegar","Salt & pepper, to taste","1400g (7 cups) day-old cooked rice","75g (5 Tbsp) soy sauce","45g (3 Tbsp) fish sauce","75g (4 Tbsp) honey","45g (3 Tbsp) rice vinegar","45g (3 Tbsp) sesame oil","600g (4 cups) mixed frozen veggies of choice","Chopped green onions","45g (3 Tbsp) sesame oil","400g egg whites","6 whole eggs","1 Tbsp butter"]'::jsonb, '["Prepare the Chicken: Slice the chicken thighs in half and add them to the slow cooker. Pour chili garlic sauce, soy sauce, honey, rice vinegar, minced ginger, salt, pepper, and sesame oil. Mix to coat evenly, cover, and cook on high for 2-3 hours or low for 3-4 hours until tender. Use tongs to break up the chicken when done.","Prepare the Rice: Spread day-old or precooked rice on a large sheet pan. Mix soy sauce, fish sauce, honey, rice vinegar, and sesame oil in a bowl, then pour over the rice and toss to coat. Broil the Rice & Veggies: Preheat the oven to 475F. Broil the rice for 10-25 minutes, checking every 5 minutes until crispy and slightly browned. Remove from the oven, scrape the edges, add frozen veggies, and broil for another 10-15 minutes until veggies are heated. Transfer the rice and veggies to a bowl and mix with the cooked chicken.","Cook the Eggs: In the same pan, spread the egg whites, whole eggs, and butter and broil for 3-4 minutes or until set. Chop eggs and add to the rice, then mix in the remaining sesame oil and chopped green onions. Stir well.","Prepare the Spicy Mayo: In a bowl, mix Greek yogurt, mayo, gochujang, sriracha, rice vinegar, salt, and pepper, adding water if needed to reach the desired consistency. Drizzle or mix into the fried rice. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add crushed peanuts, avocado slices, or extra sriracha for added flavor & texture.', 13) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-butter-chicken-rice-bowls', 'Butter Chicken Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 7, 600, 48, 65, 20, '["900g (32oz) chicken breast, diced Yogurt","300g full-fat Greek yogurt","45g (3 Tbsp) butter","480g (2 cups) basmati rice","1 Tbsp chicken bouillon","1 Tbsp sugar","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)","45g (3 Tbsp) butter","2 onions, diced","2 Tbsp tomato paste","2 Tbsp garlic paste","2 Tbsp ginger paste","2 Tbsp paprika","2 Tbsp garam masala","1 tsp cayenne","1 tsp cumin","1 tsp coriander","2 tsp salt 1 (14oz) can of crushed fire-roasted tomatoes","Dash of black pepper"]'::jsonb, '["Make the Butter Sauce: Melt butter in a large skillet over medium heat. Add chopped onions and cook until caramelized. Stir in tomato paste, garlic paste, and ginger paste, cooking for 2-3 minutes until fragrant. Add paprika, cayenne, garam masala, cumin, coriander, salt, and black pepper, stirring to combine.","Blend the Sauce: Deglaze the pan with fire-roasted tomatoes and a splash of water. Simmer for 2-3 minutes. Transfer to a blender, optionally adding chicken bouillon and sugar, and blend for 2 minutes until smooth.","Cook the Chicken: Dice chicken breast, then place it in the slow cooker. Pour butter sauce over, ensuring the chicken is fully coated. Cover and cook on high for 2-3 hours or low for 3-4 hours until tender.","Finish the Sauce: Stir in Greek yogurt and additional butter, mixing well. Cover and let sit for 10-15 minutes to meld flavors while the sauce thickens.","Prepare the Rice: In a medium saucepan, bring chicken bone broth and butter to a boil. Stir in basmati rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off heat and let sit, covered, for 10 minutes before fluffing with a fork. Serve & Store: Mix the rice into the butter chicken or keep it separate for portioning. Divide into 7 meal prep containers (~16oz per serving). Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add chopped cashews, fresh cilantro, or a drizzle of cream for more flavor & richness.', 14) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-brisket-queso-mac-n-cheese', 'Brisket Queso Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 700, 55, 75, 24, '["900g (32oz) flat-cut brisket, trimmed","400g (14oz) crushed fire-roasted tomatoes","120g red enchilada sauce","200g (7oz) chipotle peppers in adobo","60g (4 Tbsp) green chiles","75g (5 Tbsp) honey","1 Tbsp salt","2 tsp onion powder","2 tsp black pepper","750g pasta of choice","800g full-fat cottage cheese","150g American cheese, shredded","200g extra sharp cheddar cheese, shredded","100g red enchilada sauce","Salt & pepper, to taste","1 tsp nutritional yeast","Chopped cilantro"]'::jsonb, '["Prepare the Brisket: Trim the flat-cut brisket by removing excess separable fat. Add crushed fire-roasted tomatoes, red enchilada sauce, chipotle peppers, green chiles, honey, salt, onion powder, and black pepper in the slow cooker. Stir to coat evenly. Cover and cook on high for 4–5 hours or low for 5–6 hours until tender and easy to shred.","Prepare the Queso Sauce: While the brisket cooks, blend cottage cheese, American cheese, cheddar cheese, red enchilada sauce, salt, pepper, and nutritional yeast (if using) until smooth. If the mixture is too thick, lightly heat it in a pan or microwave before blending again. Set aside.","Cook the Pasta: Bring a large pot of salted water to a boil. Add pasta and cook until halfway done, then drain and set aside. Shred the Brisket & Combine: Once the brisket is fully cooked, remove it from the slow cooker and shred it using two forks. Return the sliced brisket to the slow cooker, mixing it with the cooking liquid. Stir in the blended queso sauce and half- cooked pasta, ensuring everything is evenly coated. Cover and cook on high for 15– 20 minutes or until the sauce thickens and the pasta finishes cooking. Serve & Store: Add chopped cilantro (if using) and stir well. Divide into 10 meal prep containers (~16oz per serving). Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with crushed tortilla chips, jalapeños, or extra shredded cheese for added texture & flavor.', 15) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-avocado-chicken-rice-bowls', 'Avocado Chicken Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 9, 650, 50, 70, 22, '["1340g (48oz) chicken breast, diced","8 tomatillos, diced (300g)","45g (3 Tbsp) avocado oil","1 Tbsp salt","1 Tbsp garlic powder","1 Tbsp onion powder","Juice of lemon","720g (3 cups) rice of choice","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)","5 poblano peppers","5 jalapeños","8 cloves garlic","400g full-fat Greek yogurt","120g whole milk","Juice of","1 lemon","400g avocado Handful of cilantro leaves","Salt & pepper, to taste"]'::jsonb, '["Prepare the Chicken: Dice chicken breast and add to the slow cooker with tomatillos, cilantro stems, salt, garlic powder, onion powder, avocado oil, and lemon juice. Mix well and cook on high for 2-3 hours or low for 3-4 hours.","Roast the Peppers: Preheat the oven to 400F (200C). De-seed the poblanos and jalapeños, then roast them with garlic cloves for 30-35 minutes until lightly charred. Once cooled, peel the skin off the poblanos.","Blend the Sauce: In a blender, combine roasted peppers, garlic, Greek yogurt, cilantro leaves, whole milk, lemon juice, avocado, salt, and pepper. Blend until smooth.","Cook the Rice: Bring chicken bone broth and butter to a boil in a medium saucepan. Stir in rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the heat and let sit, covered, for 10 minutes before fluffing with a fork.","Finish the Chicken: Once it is fully cooked, leave it cubed or shred it with two forks. Pour the poblano avocado sauce over the chicken in the slow cooker and stir to coat it evenly. Serve & Store: Divide rice into nine meal prep containers, topping each with chicken and sauce (~16oz per serving). Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add crumbled queso fresco, toasted pepitas, or extra cilantro for flavor & texture.', 16) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-hawaiian-bbq-chicken-rice-bowls', 'Hawaiian BBQ Chicken Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 650, 50, 75, 12, '["1790g (64oz) boneless, skinless chicken thighs","180g BBQ sauce","60g (4 Tbsp) soy sauce","20g (1 Tbsp) fish sauce","30g (2 Tbsp) grated ginger","900g (5 cups) fresh pineapple, diced","Garlic powder, onion powder, smoked paprika, & black pepper, to taste","3 Tbsp cornstarch 3","720g (4 cups) rice of choice","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)","180g BBQ sauce","2 stalks green onions, chopped"]'::jsonb, '["Prepare the Marinade: Grate ginger and whisk together BBQ sauce, soy sauce, fish sauce, garlic powder, onion powder, smoked paprika, and black pepper in a bowl until smooth. Cut pineapple into bite-sized chunks.","Slow Cook the Chicken: Place chicken thighs and pineapple into the slow cooker. Pour the marinade over the chicken and pineapple, stirring to coat evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours until the chicken is tender.","Thicken the Sauce: Mix cornstarch and water to create a slurry. Stir it into the slow cooker and mix well to thicken the sauce. Lightly shred the chicken, leaving some larger pieces intact for texture. Stir in extra BBQ sauce and chopped green onions.","Cook the Rice: Bring chicken bone broth and butter to a boil in a medium saucepan. Stir in rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the heat and let sit, covered, for 10 minutes before fluffing with a fork. Serve & Store: Divide rice and Hawaiian BBQ chicken into 10 meal prep containers (~16oz per serving). Let cool before storing in freezer- safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with toasted coconut flakes, sesame seeds, or an extra drizzle of BBQ sauce for added flavor.', 17) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-spicy-steak-pasta', 'Spicy Steak Pasta', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 650, 50, 80, 18, '["Steak","900g (32oz) flank steak or lean steak of choice, cubed","790g (28oz) fire-roasted tomatoes","5 guajillo chiles, de-stemmed & de-seeded","4 chile de arbol, de-stemmed & de-seeded","15g (1 Tbsp) soy sauce","75g (5 Tbsp) honey","1 Tbsp salt","2 tsp onion powder","2 tsp paprika","2 tsp black pepper","1 shallot","8 cloves garlic","400g full-fat Greek yogurt","90g Parmigiano Reggiano, grated","90g goat cheese","300g whole milk","Red chili flakes & chives, for garnish","750g rigatoni pasta"]'::jsonb, '["Roast the Aromatics: Preheat oven to 400F (200C). Wrap shallot and garlic in foil and roast for 15-30 minutes until softened (or pan-fried if preferred).","Prepare the Sauce: Microwave guajillo and chile de arbol peppers for 20 seconds (or toast in a dry pan for 30-45 seconds). Blend roasted shallot, garlic, fire- roasted tomatoes, guajillo, chile de arbol, soy sauce, honey, salt, onion powder, paprika, and black pepper until smooth.","Slow Cook the Steak: Place cubed steak in the slow cooker and pour the blended sauce. Stir to coat, cover, and cook on high for 4-5 hours or low for 5-6 hours until tender.","Cook the Pasta: Bring a large pot of salted water to a boil. Add rigatoni and cook until halfway done, then drain and set aside.","Prepare the Cheese Sauce: Grate Parmigiano Reggiano and add to the slow cooker with goat cheese, Greek yogurt, and whole milk. Stir well to incorporate.","Combine Everything: Mix the half-cooked pasta in the slow cooker. Cover and cook on low for 20-25 minutes until the sauce thickens and the pasta is tender. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Garnish with red chili flakes & chives. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add extra grated cheese, fresh basil, or crushed red pepper for depth.', 18) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chicken-tinga-green-rice', 'Chicken Tinga & Green Rice', 'meal', '', '["lunch","dinner"]'::jsonb, 7, 700, 55, 70, 22, '["670g (24oz) boneless, skinless chicken thighs","670g (24oz) chicken breasts","60g (4 Tbsp) olive oil","2 white onions, diced","60g (4 Tbsp) minced garlic","20g tomato paste","794g (28oz) fire-roasted diced tomatoes","60g (4 Tbsp) apple cider vinegar","1 can chipotle peppers with adobo","3 bay leaves","75g Cotija cheese","Chopped cilantro leaves Spice Blend: 5 tsp oregano","1 tsp smoked paprika","1 tsp cumin","1 Tbsp salt Black pepper, to taste Jalapeño","480g (3 cups) short-grain rice","500g chicken bone broth","200g water Handful cilantro stems","2 tsp minced garlic","1 jalapeño pepper","20g avocado oil","Pinch of salt"]'::jsonb, '["Prepare the Tinga Sauce: Dice onions and cook in a large skillet over medium-high heat until translucent and beginning to brown, stirring occasionally. Add olive oil, minced garlic, and tomato paste, mixing well to coat the onions. Cook until caramelized, about 8-10 minutes.","Blend the Sauce: Stir in fire-roasted diced tomatoes and simmer until most of the liquid reduces, about 5 minutes. Transfer the mixture to a blender. Add oregano, smoked paprika, cumin, salt, black pepper, apple cider vinegar, and chipotle peppers in adobo. Blend until smooth.","Slow Cook the Chicken: Cut chicken breast into large chunks and place in the slow cooker with chicken thighs. Pour of the blended sauce over the chicken, reserving the rest. Stir to coat evenly, then add 3 bay leaves on top. Cover and cook on high for 2-3 hours or low for 3-4 hours until the chicken is tender.","Make the Green Rice: Blend bone broth, water, cilantro stems, minced garlic, jalapeño, avocado oil, and salt until smooth. Pour into a pot with short-grain rice, bring to a boil, cover, and reduce heat to low for 20 minutes. Remove from heat and let sit for 5 minutes.","Shred the Chicken: Remove bay leaves, shred the chicken directly in the slow cooker, and stir in the reserved sauce. Adjust seasoning if needed. Serve & Store: Divide green rice and chicken tinga into 7 meal prep containers (~16oz per serving). Top with Cotija cheese and chopped cilantro. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add lime wedges, extra jalapeños, or sliced avocado for enhanced flavor.', 19) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-teriyaki-chicken-rice-bowls', 'Teriyaki Chicken Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 8, 675, 50, 80, 20, '["Chicken","1340g (48oz) boneless, skinless chicken thighs","90g (6 Tbsp) soy sauce","40g (2 Tbsp) dark soy sauce","100g (5 Tbsp) honey","75g (5 Tbsp) mirin","40g (2 Tbsp) ginger paste","20g (1 Tbsp) garlic paste","3 Tbsp cornstarch 4","2 stalks green onions, chopped","600g (3 cups) short grain or sushi rice, dry weight","1 Tbsp butter","1 cups chicken bone broth (amount unclear in the source)","120g full-fat mayo","120g full-fat Greek yogurt","100g (6 Tbsp) sriracha","Salt, pepper, garlic powder, to taste","Splash of whole milk"]'::jsonb, '["Prepare the Chicken: Place chicken thighs in the slow cooker. Pour in soy sauce, dark soy sauce, honey, mirin, ginger paste, and garlic paste, stirring to coat evenly.","Slow Cook the Chicken: Cover and cook on high for 4-5 hours or low for 5+ hours until tender. Once done, lightly shred the chicken in the slow cooker, mixing it with the sauce.","Thicken the Sauce: Mix cornstarch and cold water in a small bowl to create a slurry. Stir the slurry into the slow cooker and let sit uncovered for 15-20 minutes until the sauce thickens.","Cook the Rice: Bring chicken bone broth and butter to a boil in a medium saucepan. Stir in rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the heat and let sit, covered, for 10 minutes before fluffing with a fork.","Make the Yum Yum Sauce: In a bowl, mix mayo, Greek yogurt, sriracha, salt, pepper, and garlic powder. Add a splash of milk to adjust consistency as needed. Combine & Serve: Mix cooked rice into the chicken or separate it for easier portioning. Add chopped green onions, reserving some for garnish if desired. Store & Reheat: Divide into eight meal prep containers (~16oz per serving) and drizzle with Yum Yum sauce. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add sesame seeds, extra sriracha, or a fried egg for more flavor & texture.', 20) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-cheesy-chipotle-chicken-pasta', 'Cheesy Chipotle Chicken Pasta', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 650, 50, 80, 20, '["Chicken","780g (28oz) chicken breast, diced","75g (5 Tbsp) adobo sauce","5 chipotle peppers, minced","2 tsp garlic powder","2 tsp onion powder","1 Tbsp salt","1 tsp chicken bouillon","360g water","750g pasta of choice","750g (3 cups) full-fat cottage cheese","150g full-fat cream cheese","75g Parmigiano Reggiano, grated","75g mozzarella, shredded","75g (4 Tbsp) honey","360g whole milk","Salt & pepper, to taste","Chopped chives"]'::jsonb, '["Prepare the Chicken: Dice chicken breast and add to the slow cooker with adobo sauce, minced chipotle peppers, salt, garlic powder, onion powder, chicken bouillon, and water. Stir well to coat evenly. Cover and cook on high for 2-3 hours or low for 4-5 hours until tender.","Cook the Pasta: Bring a large pot of salted water to a boil. Add pasta and cook until halfway done, then drain and set aside.","Make the Cheese Sauce: In a blender, combine Parmigiano Reggiano, cottage cheese, cream cheese, mozzarella, honey, whole milk, salt, and pepper. Blend until smooth.","Combine Everything: Shred the cooked chicken directly in the slow cooker. Add the half-cooked pasta and cup of reserved pasta water. Pour in the blended cheese sauce, stirring thoroughly to coat everything evenly.","Final Cook: Cover and cook on low for 20-30 minutes until the sauce thickens and the pasta is tender. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Garnish with chopped chives. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with extra shredded cheese, cilantro, or crispy tortilla strips for added flavor & texture.', 21) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-lemon-harissa-chicken-pasta', 'Lemon Harissa Chicken Pasta', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 700, 55, 75, 22, '["1340g (48oz) boneless, skinless chicken thighs","2 yellow onions, diced","90g (6 Tbsp) harissa paste (divided: 4 Tbsp for cooking","3 Tbsp for finishing)","75g (5 Tbsp) sun-dried tomatoes, chopped","20g tomato paste","30g (2 Tbsp) honey","2 tsp smoked paprika","2 tsp dried thyme","2 tsp dried oregano","1 tsp garlic powder","1 Tbsp salt","Dash of black pepper","Juice and zest of","2 lemons","200g feta cheese, crumbled","500g (2 cups) whole milk","750g penne pasta","200g store-bought tzatziki","200g full-fat Greek yogurt","Salt & garlic powder, to taste","Chopped chives"]'::jsonb, '["Prepare the Chicken & Sauce: Dice yellow onions and chop sun-dried tomatoes. Add to slow cooker with chicken thighs, 4 Tbsp harissa paste, tomato paste, honey, smoked paprika, thyme, oregano, garlic powder, salt, and black pepper. Stir well to coat the chicken evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours until chicken is tender.","Shred the Chicken: Once the chicken is cooked, shred it directly in the slow cooker using two forks. Add lemon juice, zest, harissa paste, and crumbled feta cheese. Stir to combine, then cover and cook on high for 10 minutes to let the flavors meld.","Cook the Pasta: Bring a large pot of salted water to a boil. Add penne pasta and cook until halfway done, then drain and set aside. Combine & Cook: Add the half-cooked pasta and whole milk to the slow cooker. Stir everything together to coat the pasta evenly. Cover and cook on low for 20-30 minutes or until the pasta is fully cooked and the sauce has thickened.","Prepare the Tzatziki: Mix store-bought tzatziki and Greek yogurt in a bowl. Add salt and garlic powder to taste, stirring until smooth. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Top each pasta bowl with a dollop of tzatziki and a sprinkle of chives. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add extra feta, kalamata olives, or a drizzle of olive oil for more richness.', 22) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-honey-chipotle-chicken-burrito-bowls', 'Honey Chipotle Chicken Burrito Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 7, 675, 55, 75, 20, '["Chicken","1360g (48oz) boneless, skinless chicken thighs","300g orange juice","200g (7oz) chipotle peppers in adobo","60g (4 Tbsp) soy sauce","40g (2 Tbsp) apple cider vinegar","3 Tbsp garlic purée","2 tsp cumin","1 Tbsp salt","2 tsp black pepper","2 tsp onion powder","100g (5 Tbsp) honey","20g (1 Tbsp) avocado oil","500g (2 cups) Jasmine rice, dry weight","1 Tbsp butter","1 cups chicken bone broth Toppings (amount unclear in the source)","75g full-fat Greek yogurt Pico de gallo, to taste","Fresh cilantro, for garnish"]'::jsonb, '["Make the Marinade: Blend orange juice, chipotle peppers, soy sauce, apple cider vinegar, garlic purée, cumin, salt, black pepper, onion powder, honey, avocado oil, and cilantro stems until completely smooth.","Slow Cook the Chicken: Place chicken thighs in the slow cooker. Pour the marinade over the chicken and stir to coat evenly. Cover and cook on high for 2-3 hours or low for 3-4 hours until tender.","Cook the Rice: In a medium saucepan, bring chicken bone broth and butter to a boil. Stir in Jasmine rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off heat and let sit, covered, for 10 minutes before fluffing with a fork.","Shred the Chicken: Once the chicken is fully cooked, use two forks to shred it directly in the slow cooker. Stir the shredded chicken back into the sauce to absorb all the flavor. Assemble & Serve: Mix cooked rice into the chicken or keep separate for easier portioning. Divide into 7 meal prep containers (~16oz per serving) and top each burrito bowl with Greek yogurt, pico de gallo, and chopped cilantro. Store & Reheat: Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add avocado slices, shredded cheese, or a squeeze of fresh lime for extra flavor.', 23) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chorizo-queso-mac-n-cheese', 'Chorizo Queso Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 750, 55, 85, 30, '["Meat","907g (32oz) 93% lean ground beef","227g (8oz) pork chorizo","1 Tbsp coarse salt","1 Tbsp ground paprika","1 Tbsp dried oregano","1 tsp ground cumin","1 tsp black pepper","150g red enchilada sauce","400g (14oz) fire-roasted tomatoes","3 Tbsp garlic purée","1 Tbsp chipotle peppers, minced","1 Tbsp adobo sauce","60g (4 Tbsp) apple cider vinegar","750g pasta of choice","900g (3 cups) full-fat cottage cheese","150g full-fat cream cheese","200g extra sharp cheddar cheese, shredded","40g cheddar powder","300g red enchilada sauce","360g whole milk","2 orange bell peppers, diced","2 red bell peppers, diced","1 onion, diced","Chopped cilantro"]'::jsonb, '["Roast the Vegetables: Preheat oven to 400F (200C). Spread bell peppers and onion on a baking sheet and roast for 20-25 minutes until tender. Slow Cook the Meat & Sauce: In the slow cooker, combine ground beef, chorizo, salt, paprika, oregano, cumin, black pepper, enchilada sauce, fire-roasted tomatoes, garlic purée, chipotle peppers, adobo sauce, and apple cider vinegar. Stir to coat evenly. Add roasted vegetables, cover, and cook on high for 2-3 hours or low for 3-4 hours until meat is tender.","Cook the Pasta: Bring a large pot of salted water to a boil. Add pasta and cook until halfway done, then drain and set aside.","Make the Queso Sauce: In a blender, combine cottage cheese, cream cheese, cheddar cheese, cheddar powder, enchilada sauce, and whole milk. Blend until smooth. Combine & Cook: Add the half-cooked pasta and queso sauce to the slow cooker. Stir well, cover, and cook on low for 15-20 minutes until the sauce thickens and pasta is tender. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Garnish with chopped cilantro if desired. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with extra shredded cheese, hot sauce, or crushed tortilla chips for crunch.', 24) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-lasagna-bowls', 'Lasagna Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 700, 55, 80, 25, '["907g (32oz) 93% lean ground beef","30g (2 Tbsp) tomato paste","840g (54oz) crushed tomatoes (two","28oz cans)","960g (32oz) bone broth (two","16oz boxes)","1 Tbsp onion powder","1 Tbsp garlic powder","1 Tbsp salt","1 Tbsp Italian herbs","1 tsp black pepper","900g (3 cups) full-fat cottage cheese","150g Parmigiano Reggiano, shredded","100g mozzarella, shredded","180g whole milk","500g oven-ready lasagna noodles, broken into pieces","300g water","50g whole milk ricotta","Fresh chopped basil"]'::jsonb, '["Slow Cook the Beef: Add ground beef to the slow cooker. Add tomato paste, crushed tomatoes, bone broth, onion powder, garlic powder, salt, Italian herbs, and black pepper. Stir well, breaking up any large chunks of beef. Cover and cook on high for 3-4 hours or low for 4+ hours until the beef is tender and flavors meld.","Add the Pasta: Once the beef is done, break up oven-ready lasagna sheets and add them to the slow cooker. Pour in water and stir to separate and submerge all pasta pieces. Cover and cook on high for 20-30 minutes until pasta is tender.","Prepare the Cheese Sauce: In a blender, combine cottage cheese, shredded Parmigiano Reggiano, shredded mozzarella, and whole milk. Blend until smooth. Combine & Cook: Pour the cheese sauce into the slow cooker, stirring until fully incorporated. Cover and let sit for another 10 minutes to thicken. Serve & Store: Divide the mixture into 10 meal prep containers (~16oz per serving). Top each bowl with ricotta and fresh basil. Let the mixture cool before storing it in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add extra mozzarella, crushed red pepper, or Italian sausage for more flavor.', 25) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chicken-bacon-ranch-mac-n-cheese', 'Chicken Bacon Ranch Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 11, 650, 55, 75, 22, '["Chicken","896g (32oz) chicken breast, diced","6 slices turkey bacon, chopped","1 packet ranch seasoning","45g (3 Tbsp) hot honey","1 Tbsp fresh dill, chopped","Garlic powder, black pepper, & red chili flakes, to taste","3 sweet onions, diced","6 jalapeños or Fresno chilis, sliced","8 cloves garlic, minced","480g (16oz) chicken bone broth","900g (3 cups) full-fat cottage cheese","200g Parmigiano Reggiano, shredded","500g (2 cups) whole milk","1 tsp garlic powder","1 tsp onion powder","Salt & pepper, to taste","750g pasta of choice (increase for more carbs & energy) Topping","10 slices center-cut bacon, cooked & chopped Handful of chopped chives"]'::jsonb, '["Prepare the Broth Base: Mince garlic and dice onions. In a large skillet, saut onions until browned. Add jalapeños and garlic, cooking until softened. Pour in chicken bone broth, boil, and reduce the liquid completely. Set aside.","Slow Cook the Chicken: Dice chicken breast and chop dill. Add turkey bacon, ranch seasoning, hot honey, garlic powder, black pepper, and red chili flakes to the slow cooker. Pour in broth base, stir, and cook on high for 2-3 hours or low for 3-4 hours until chicken is tender. Lightly shred with tongs.","Cook the Pasta: Bring a large pot of salted water to a boil. Add pasta and cook until halfway done, then drain and set aside.","Make the Cheese Sauce: In a blender, combine Parmigiano Reggiano, cottage cheese, whole milk, garlic powder, onion powder, salt, and pepper. Blend until smooth. Add the cheese sauce, chopped chives, and half-cooked pasta to the slow cooker. Stir well, cover, and cook on low for 10-15 minutes until pasta is tender and sauce thickens.","Prepare the Bacon Topping: Bake center-cut bacon at 400F for 15-20 minutes until crispy. Chop and stir into the slow cooker. Serve & Store: Divide into 11 meal prep containers (~16oz per serving). Garnish with chopped chives. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add extra bacon, cheddar cheese, or crushed red pepper for more heat.', 26) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chimichurri-steak-rice-bowls', 'Chimichurri Steak Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 9, 700, 55, 80, 25, '["Steak","1340g (48oz) flank steak or lean steak of choice","1 yellow onion, diced","15g (1 Tbsp) minced garlic","1 Tbsp salt","2 tsp black pepper","2 tsp garlic powder","2 tsp oregano","30g (2 Tbsp) red wine vinegar","15g (1 Tbsp) olive oil","240g (1 cup) pured fresh pineapple (essential for tenderizing)","600g (3 cups) short grain rice, uncooked","900g (3 cups) chicken bone broth","5g (1 tsp) olive oil","1 yellow onion, diced","1 Tbsp minced garlic","1 Tbsp turmeric","60g olive oil","60g red wine vinegar","1 bunch chopped cilantro","4 cloves minced garlic","2 small red chilies (e.g., red jalapeños or Fresno chilies), minced","1 tsp dried oregano","1 tsp coarse salt","tsp black pepper (amount unclear in the source)"]'::jsonb, '["Marinate & Slow Cook the Steak: Add flank steak to the slow cooker. Dice onion and mince garlic, then add with salt, black pepper, garlic powder, oregano, olive oil, red wine vinegar, and pured fresh pineapple. Stir to coat evenly. Cover and cook on low for 6-8 hours until steak is tender and shreddable.","Prepare the Chimichurri: Finely chop red chilies, cilantro, and mince garlic. Combine in a bowl with olive oil, red wine vinegar, dried oregano, coarse salt, and black pepper. Mix well and refrigerate to let flavors meld.","Cook the Yellow Rice: Heat olive oil in a pan, then saut diced onion until translucent. Add minced garlic, turmeric, and salt, stirring until fragrant. Stir in short grain rice, then pour in chicken bone broth. Bring to a boil, cover, reduce to low, and simmer for 20-25 minutes. Let sit covered for 10 minutes before fluffing.","Shred the Steak: Once cooked, shred steak in the slow cooker and mix in chimichurri sauce, reserving some for garnish if desired. Serve & Store: Portion steak and rice into 9 meal prep containers (~16oz per serving). Garnish with extra chimichurri. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with sliced avocado, extra red chili, or a fried egg for more flavor.', 27) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-buffalo-chicken-bacon-mac-n-cheese', 'Buffalo Chicken & Bacon Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 11, 700, 55, 85, 25, '["Chicken","900g (32oz) chicken breast, diced","120g buffalo sauce","40g (2 Tbsp) Worcestershire sauce","20g (1 Tbsp) chicken bouillon","Salt, pepper, & garlic powder, to taste","3 orange bell peppers, diced","2 onions, diced","750g pasta of choice","900g (3 cups) full-fat cottage cheese","75g full-fat cream cheese","150g extra sharp cheddar cheese, shredded","75g Parmigiano Reggiano, shredded","150g buffalo sauce","400g whole milk","40g (2 Tbsp) honey","Salt & pepper, to taste","18 slices center-cut bacon, cooked & chopped","Chopped chives"]'::jsonb, '["Roast the Vegetables: Preheat oven to 400F (200C). Spread bell peppers and onions on a baking sheet and roast for 20-25 minutes until lightly charred.","Slow Cook the Chicken: Dice chicken breast and add to the slow cooker with buffalo sauce, Worcestershire sauce, chicken bouillon, salt, pepper, and garlic powder. Stir in roasted vegetables to coat well. Cover and cook on high for 2-3 hours or low for 4-5 hours until tender.","Cook the Pasta: Bring a large pot of salted water to a boil. Add pasta and cook until halfway done, then drain and set aside.","Make the Cheese Sauce: In a blender, combine cottage cheese, cream cheese, cheddar cheese, Parmigiano Reggiano, buffalo sauce, whole milk, honey, salt, and pepper. Blend until smooth. Combine & Cook: Add the half-cooked pasta and buffalo cheese sauce to the slow cooker. Stir well, cover, and cook on low for 20-30 minutes until the sauce thickens and pasta is tender.","Prepare the Bacon Topping: Meanwhile, bake center-cut bacon at 400F for 15-20 minutes until crispy. Chop and stir into the slow cooker. Serve & Store: Divide into 11 meal prep containers (~16oz per serving). Garnish with chopped chives. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with extra bacon, shredded cheese, or a drizzle of ranch for more flavor.', 28) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-korean-bbq-beef-rice-bowls', 'Korean BBQ Beef Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 763, 53, 72, 33, '["Steak","1340g (48oz) flat cut brisket or chuck eye roast","5 Tbsp soy sauce","60g (4 Tbsp) gochujang","60g (4 Tbsp) mirin","50g (2 Tbsp) honey","40g (2 Tbsp) garlic purée","20g (1 Tbsp) ginger purée Black pepper, to taste","700g (3 cups) short grain rice, uncooked","1000g (4 cups) chicken bone broth","250g (1 cup) full-fat Greek yogurt or skyr","50g (3 Tbsp) gochujang","15g (1 Tbsp) chili crisp","50g (3 Tbsp) whole milk","Salt & pepper, to taste","Sesame seeds","Chopped green onions","40g (3 Tbsp) toasted sesame oil","80g (5 Tbsp) premium oyster sauce (Lee Kum Kee/Lucky Brand recommended)"]'::jsonb, '["Marinate & Slow Cook the Beef: Trim excess fat from brisket or chuck eye roast, then place it in the slow cooker. Add soy sauce, gochujang, mirin, honey, garlic purée, ginger purée, and black pepper. Mix thoroughly to coat evenly. Cover and cook on high for 5-6 hours or low for 6+ hours until beef is tender and easily shreds. Shred the Beef & Add Flavor: Once the beef is done, shred it using two forks or chop it into bite-sized pieces. Stir in oyster sauce and toasted sesame oil. Let sit for a few minutes to absorb the flavors.","Cook the Rice: In a medium saucepan, bring chicken bone broth to a boil. Stir in short grain rice, reduce heat to low, cover, and simmer for 20-25 minutes. Turn off the heat and let sit, covered, for 10 minutes before fluffing with a fork.","Make the Spicy Cream Sauce: In a small bowl, mix Greek yogurt, gochujang, chili crisp, whole milk, salt, and pepper. Stir until smooth. Assemble & Store: Divide cooked rice into 10 meal prep containers (~16oz per serving). Top each with Korean BBQ beef, sesame seeds, and chopped green onions. Drizzle with spicy cream sauce or serve on the side. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with sauted mushrooms, kimchi, or a fried egg for extra flavor.', 29) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-spicy-chicken-alfredo', 'Spicy Chicken Alfredo', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 733, 60, 67, 23, '["Chicken","900g (32oz) chicken breast, diced","50g Parmigiano Reggiano, shredded","30g (2 Tbsp) minced garlic","1 Tbsp salt","2 tsp crushed red pepper","2 tsp garlic powder","2 tsp onion powder","1 tsp black pepper","tsp cayenne pepper (amount unclear in the source)","120g chicken bone broth","45g (3 Tbsp) butter","750g pasta of choice (increase for more carbs & energy)","240g (1 cup) pasta water","Red","900g (3 cups) full-fat cottage cheese","150g full-fat cream cheese","150g Parmigiano Reggiano, shredded","300g whole milk","Salt, pepper, & red chili flakes, to taste","5 red bell peppers","10 cloves garlic","1 tsp oil of choice","Chopped parsley"]'::jsonb, '["Slow Cook the Chicken: Shred Parmigiano Reggiano and dice chicken breast. Add to slow cooker with minced garlic, salt, crushed red pepper, garlic powder, onion powder, black pepper, cayenne pepper, chicken bone broth, and butter. Stir well, cover, and cook on high for 2-3 hours or low for 4-5 hours until tender. Shred chicken once cooked.","Roast the Vegetables: Preheat the oven to 450F (230C). Place red bell peppers and garlic cloves (wrapped in foil with oil) on a baking sheet. Roast for 30-50 minutes until softened and slightly charred. Once cooled, peel the peppers.","Prepare the Alfredo Sauce: In a blender, combine roasted peppers, roasted garlic, cottage cheese, cream cheese, milk, red chili flakes, salt, and pepper. Blend until smooth.","Cook the Pasta: Bring a large pot of salted water to a boil. Add pasta and cook until halfway done, then drain and set aside, reserving 1 cup of pasta water. Combine & Cook: Add half-cooked pasta, reserved pasta water, and blended Alfredo sauce to the slow cooker with the chicken. Stir well, cover, and cook on low for 15-20 minutes until pasta is tender and sauce thickens. Serve & Store: Divide into 10 meal prep containers (~16oz per serving). Garnish with chopped parsley. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with extra chili flakes, Parmesan, or grilled chicken for more texture.', 30) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-slow-cooker-chili', 'Slow Cooker Chili', 'meal', '', '["lunch","dinner"]'::jsonb, 12, 735, 51, 50, 44, '["1340g (48 oz) 80/20 ground beef","3 yellow onions, diced","10 cloves garlic, minced","2 Tbsp butter","3 Tbsp tomato paste","480g (2 cups) beef bone broth","480g (2 cups) red enchilada sauce","3 Tbsp apple cider vinegar","794g (28oz) can of fire-roasted diced tomatoes","1 can (7oz) chipotle peppers","425g (15oz) black beans","20g (1 Tbsp) honey","salt, ancho chili powder, garlic powder, onion powder","2 tsp each: smoked paprika, cumin, oregano","1 tsp each: black pepper, cayenne","tsp cinnamon Toppings (amount unclear in the source)","400g full-fat skyr or Greek yogurt","100g full-fat cream cheese","200g (2 cups) sharp cheddar cheese Handful of fresh cilantro"]'::jsonb, '["Saut Aromatics: In a hot pan over high heat, cook diced yellow onions until translucent and starting to brown. Lower the heat to medium, add minced garlic, butter, and tomato paste, and simmer for 5 minutes.","Slow Cook the Chili: Transfer the onion, garlic, and tomato paste mixture to the slow cooker. Add ground beef, beef bone broth, red enchilada sauce, apple cider vinegar, fire-roasted diced tomatoes, chipotle peppers, black beans, honey, and all spices. Stir well to combine.","Cook Until Tender: Cover and cook on low for 4-5 hours or high for 3-4 hours, until the beef is tender and fully cooked. Break up the meat with a wooden spoon, mixing until evenly combined. Add Cheese & Finish: Grate cheddar cheese and stir in softened cream cheese and shredded cheddar until fully melted and creamy. Serve & Store: Divide into 12 meal prep containers (~11oz per serving). Top each bowl with a dollop of Greek yogurt, shredded cheddar, and fresh chopped cilantro. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with cornbread, rice, or a fried egg for extra calories.', 31) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-slow-cooker-chili-mac', 'Slow Cooker Chili Mac', 'meal', '', '["lunch","dinner"]'::jsonb, 12, 785, 52, 75, 42, '["1340g (48 oz) 80/20 ground beef","3 yellow onions, diced","10 cloves garlic, minced","2 Tbsp butter","3 Tbsp tomato paste","480g (2 cups) beef bone broth","480g (2 cups) red enchilada sauce","3 Tbsp apple cider vinegar","794g (28oz) can of fire-roasted diced tomatoes","1 can (7oz) chipotle peppers","425g (15oz) black beans","20g (1 Tbsp) honey","salt, ancho chili powder, garlic powder, onion powder","2 tsp each: smoked paprika, cumin, oregano","1 tsp each: black pepper, cayenne","tsp cinnamon Pasta (amount unclear in the source)","672g (24 oz) pasta of choice","800g 2% cottage cheese","200g (2 cups) full-fat skyr or Greek yogurt","200g (2 cups) sharp cheddar cheese","125g American cheese","200g whole milk Cilantro garnish"]'::jsonb, '["Saut Aromatics: In a hot pan over high heat, cook diced yellow onions until translucent and starting to brown. Lower the heat to medium, add minced garlic, butter, and tomato paste, and simmer for 5 minutes.","Slow Cook the Chili: Transfer the onion, garlic, and tomato paste mixture to the slow cooker. Add ground beef, beef bone broth, red enchilada sauce, apple cider vinegar, fire- roasted diced tomatoes, chipotle peppers, black beans, honey, and all spices. Stir well to combine.","Cook Until Tender: Cover and cook on low for 4-5 hours or high for 3-4 hours, until the beef is tender and fully cooked.","Cook the Pasta: Bring a pot of salted water to a boil. Cook the pasta halfway according to the package instructions. Drain and set aside. Combine Pasta & Chili: Once the beef is cooked, break up the meat with a wooden spoon, mixing until evenly combined. Stir in the half-cooked pasta.","Prepare Cheese Sauce: In a blender, combine cottage cheese, full-fat skyr, cheddar cheese, American cheese, and whole milk. Blend until smooth. Pour over the chili and pasta, stirring until fully incorporated.","Final Cooking Step: Cover and cook on high for 15 minutes, allowing the pasta to absorb flavor and the cheese sauce to thicken. Serve & Store: Divide into 12 meal prep containers (~11oz per serving). Garnish with fresh chopped cilantro. Let cool before storing in freezer-safe, airtight containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with sour cream, crushed tortilla chips, or avocado for extra calories.', 32) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-butter-chicken-chili', 'Butter Chicken Chili', 'meal', '', '["lunch","dinner"]'::jsonb, 7, 390, 47, 11, 17, '["1350g (48oz) ground chicken thighs","3 Tbsp smoked paprika","2 Tbsp cumin","1 Tbsp garam masala","2 tsp coriander","1 tsp cayenne","1 Tbsp salt","Dash of black pepper Lemon Yogurt Sauce : 100g Greek yogurt","Juice of lemon","Salt & garlic powder to taste","45g (3 Tbsp) butter","3 yellow onions, diced","45g (3 Tbsp) tomato paste","45g (3 Tbsp) garlic paste","45g (3 Tbsp) ginger paste spice blend","794g (28oz) can of crushed fire-roasted tomatoes","240g (1 cup) chicken bone broth","20g (1 Tbsp) honey Toppings","300g full-fat Greek yogurt or skyr","30g (2 Tbsp) butter reserved spice blend Cilantro for garnish"]'::jsonb, '["Prepare Spice Blend: Mix smoked paprika, cumin, garam masala, coriander, cayenne, salt, and black pepper in a small bowl.","Cook the Butter Sauce: Dice onions and saut over high heat until translucent. Lower heat to medium, add butter, and simmer for 5-10 minutes, stirring occasionally. Stir in tomato paste, garlic paste, ginger paste, and half the spice blend. Cook for 2-3 minutes until fragrant.","Blend the Sauce: Add crushed fire-roasted tomatoes, chicken bone broth, and honey. Simmer for 5 minutes, then transfer to a blender and blend until smooth.","Slow Cook the Chicken: Place ground chicken thighs in the slow cooker and pour the blended butter sauce over the top. Stir to coat. Cover and cook on high for 2-3 hours or low for 3-4 hours.","Break Up the Chicken: Once cooked, break up the chicken into smaller pieces, stirring to create a chili-like consistency. Final Mix-Ins: Stir in Greek yogurt (or skyr), butter, and remaining spice blend. Mix thoroughly. Cover and cook on low for 10 minutes to let flavors meld. Serve & Store: Divide into seven meal prep containers (~12oz per serving). Garnish with fresh cilantro. Let cool before storing in freezer-safe, airtight containers.","Optional Topping Sauce: In a small bowl, mix Greek yogurt, lemon juice, salt, and garlic powder. Drizzle over chili before serving."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months Reheating: Microwave for 2-3 minutes, stirring halfway through Optional add-ins: Serve with naan, rice, or avocado for extra calories.', 33) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-frozen-cheesy-buffalo-chicken-burritos', 'Frozen Cheesy Buffalo Chicken Burritos', 'meal', '', '["lunch","dinner"]'::jsonb, 14, 525, 40, 45, 22, '["1360g (48oz) boneless, skinless chicken thighs","1 tsp salt","1 tsp garlic powder","1 tsp onion powder","1 tsp paprika","1 tsp chili powder","1 packet ranch seasoning","1 Tbsp fresh chopped dill","150g buffalo sauce","750g (3 cups) full-fat cottage cheese","250g (1 cup) full-fat cream cheese","250g (1 cup) buffalo sauce","250g (2 cups) full-fat cheddar cheese","80g (4 Tbsp) honey","50g (3 Tbsp) butter Handful of chopped chives","14 large flour tortillas"]'::jsonb, '["Prepare the Chicken: Place chicken thighs in the slow cooker. Sprinkle with salt, garlic powder, onion powder, paprika, chili powder, ranch seasoning, and fresh dill. Pour in buffalo sauce and mix well. Cover and cook on high for 2-3 hours or low for 3-4 hours, until tender.","Shred the Chicken: Shred directly in the slow cooker using two forks.","Make Buffalo Cheese Sauce: Blend cottage cheese until smooth. Grate the cheddar cheese and mix it into the slow cooker with cream cheese, buffalo sauce, honey, and butter. Stir thoroughly until the mixture is smooth and creamy. Fold in chopped chives.","Thicken the Sauce: Mix two tablespoons of cornstarch with two tablespoons of cold water to create a cornstarch slurry. Stir this into the slow cooker to help thicken the sauce. Cover and let it cook on low for 10 minutes.","Chill the Mixture: Transfer the chicken mixture to the refrigerator and let it chill for 45-60 minutes to thicken.","Assemble the Burritos: Lay out 14 large tortillas and evenly divide the chicken mixture into them. Roll each tortilla tightly to form burritos. Wrap & Store: Wrap each burrito in aluminum foil and freeze them for long-term storage."]'::jsonb, 'For meal prep: Store burritos in freezer-safe bags for up to 3 months. Reheating: Microwave wrapped in a damp paper towel for 2-3 minutes, flipping halfway through. Optional add-ins: Add rice, black beans, or extra cheese for more bulk.', 34) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-miso-mac', 'Miso Mac', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 670, 49, 58, 27, '["1340g (48oz) boneless, skinless chicken thighs","60g (4 Tbsp) white miso paste","45g (3 Tbsp) mirin","1 Tbsp salt","1 Tbsp garlic powder Black pepper, to taste","1 white onion, diced","600g (2 cups) whole milk","60g (4 Tbsp) white miso paste","250g (2 cups) sharp cheddar cheese","30g (2 Tbsp) Parmigiano Reggiano","100g (1 cup) mozzarella cheese","672g (24 oz) macaroni","Juice of","1 lemon White/black sesame seeds"]'::jsonb, '["Prepare the Chicken: In a bowl, whisk together white miso paste, mirin, salt, garlic powder, and black pepper until combined. Dice onions and place them into the slow cooker with the chicken thighs. Pour the miso sauce over the chicken, stirring to coat evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours, until the chicken is tender.","Cook the Pasta: Bring a large pot of salted water to a boil and cook macaroni halfway according to package instructions. Drain and set aside.","Make the Miso Milk: In a blender, combine whole milk and white miso paste. Blend until smooth. Shred the Chicken & Add Ingredients: Once the chicken is done, lightly shred it with two forks, leaving some larger pieces for texture. Shred cheddar, Parmigiano Reggiano, and mozzarella cheese. Add to the slow cooker along with the half-cooked macaroni and miso milk. Add a pinch of salt. Cover and cook on low for 20-30 minutes, or until thickened and pasta is fully cooked. Final Mix & Serve: Stir well until fully combined. Top with sesame seeds and a squeeze of fresh lemon juice for brightness. Divide into 10 servings. Let leftovers cool before sealing in airtight, freezer-safe containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with grilled chicken, extra cheese, or chili flakes for a spicy kick.', 35) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-cheesy-southwestern-chicken-orzo', 'Cheesy Southwestern Chicken Orzo', 'meal', '', '["lunch","dinner"]'::jsonb, 12, 650, 48, 65, 22, '["Chicken","1350g (48oz) boneless, skinless chicken thighs","3 packets taco seasoning","1 Tbsp chicken bouillon","4 Tbsp Hatch green chiles","15g (1 Tbsp) soy sauce","480g (16oz) chicken bone broth","30g (2 Tbsp) butter","672g (24 oz) orzo","6 cans Amys Southwestern vegetable soup","120g (4 oz) water Hot sauce of choice, to taste","200g (2 cups) full-fat cheddar","80g extra sharp cheddar","500g (2 cups) whole milk","Chopped cilantro"]'::jsonb, '["Cook the Chicken: Add chicken thighs, taco seasoning, chicken bouillon, Hatch green chiles, soy sauce, chicken bone broth, and butter to a slow cooker. Stir to coat the chicken evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours until the chicken is tender and cooked through. Shred & Add Orzo: Once the chicken is done, shred it directly in the slow cooker using two forks. Add uncooked orzo, Amys Southwestern vegetable soup, hot sauce to taste, and water. Stir well to combine, ensuring the orzo is fully submerged in the liquid. Cover and cook on high for 30-40 minutes, stirring every 10-15 minutes, until the orzo is tender.","Make the Cheese Sauce: Shred the full-fat cheddar and extra sharp cheddar. Then add to the slow cooker along with whole milk Greek yogurt. Stir thoroughly until the cheese is melted and the sauce is creamy and evenly distributed. Taste and adjust seasoning and salt if needed. Serve & Store: Garnish with freshly chopped cilantro, divide into 12 servings, and serve immediately. Store leftovers in freezer-safe containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through Optional add-ins: Serve with avocado, extra cheese, or hot sauce for extra calories and flavor.', 36) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-jalape-o-popper-mac-n-cheese', 'Jalapeño Popper Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 620, 56, 65, 20, '["Jalapeño","900g (32oz) chicken breast","100g pickled jalapeños","30g (2 Tbsp) jalapeño brine","480g (16oz) chicken bone broth","3 sweet onions","8 jalapeños","6 slices turkey bacon","Salt, garlic powder, and pepper, to taste","30g (2 Tbsp) butter","672g (24 oz) pasta of choice","800g full-fat cottage cheese","120g cream cheese","40g (2 Tbsp) honey","180g Parmigiano Reggiano","420g whole milk","tsp garlic powder (amount unclear in the source)","tsp onion powder (amount unclear in the source)","Salt & pepper, to taste","12 slices center-cut bacon (increase from 10 for more flavor and calories)","3 Tbsp fresh chives, chopped"]'::jsonb, '["Caramelize Onions & Jalapeños: Dice sweet onions and jalapeños, then add them to a hot pan over high heat. Cook until translucent and beginning to brown. Pour chicken bone broth and butter, boil, and completely reduce the liquid.","Slow Cook the Chicken: Dice chicken breast and pickled jalapeños, then place them in the slow cooker with jalapeño brine, roasted onion and jalapeño mixture, turkey bacon, salt, garlic powder, and pepper. Stir, cover, and cook on high for 2-3 hours or low for 3-4 hours, until tender.","Bake Bacon: While the chicken cooks, bake center-cut bacon on a foil-lined sheet at 400F for 15 minutes or until crispy. Chop into small pieces and set aside.","Cook Pasta: Bring a pot of salted water to a boil and cook the pasta halfway according to the box instructions. Drain and set aside.","Make Cheese Sauce: Grate the Parmigiano Reggiano and blend with full-fat cottage cheese, 1/3-fat cream cheese, honey, whole milk, garlic powder, onion powder, salt, and pepper until smooth.","Finish in Slow Cooker: Once the chicken is done, shred it in the slow cooker. Stir in the cheese sauce and half-cooked pasta and mix well to coat. Cover and cook on high for 15 minutes to finish the pasta and thicken the sauce. Garnish & Serve: Top with crispy bacon and fresh chives. Divide into 10 servings and store leftovers in freezer-safe containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with extra cheese, avocado, or a drizzle of ranch for added calories.', 37) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-honey-harissa-chicken-rice-bowls', 'Honey Harissa Chicken Rice Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 630, 52, 66, 22, '["1790g (64oz) boneless, skinless chicken thighs","105g (7 Tbsp) harissa paste","15g (1 Tbsp) white miso paste","2 tsp smoked paprika","2 tsp dried thyme or oregano","1 tsp garlic powder","1 Tbsp salt","Dash of black pepper","80g (4 Tbsp) honey","2 Tbsp olive oil Additional Ingredients: Juice of","1 lemon 3","560g (3 cups) rice","840g (3 cups) chicken bone broth","Salt, garlic powder, dried oregano, dried thyme, rosemary","30g (2 Tbsp) butter (instead of olive oil for added richness)","200g store-bought tzatziki","200g full-fat Greek yogurt (instead of 0% for more calories)","Salt/garlic powder to taste","150g (1 cup) feta cheese","Pickled red onions, diced avocados, diced cucumbers, capers (avocado for more calories!)"]'::jsonb, '["Marinate & Cook Chicken: In a large bowl, mix harissa paste, white miso paste (if using), smoked paprika, dried thyme or oregano, garlic powder, salt, black pepper, honey, and olive oil until well combined. Place the chicken thighs into the slow cooker and pour the harissa mixture over them, ensuring all pieces are evenly coated. Cover and cook on high for 3–4 hours or low for 4–5 hours, until the chicken is tender.","Prepare the Herby Rice: While the chicken cooks, combine rice, chicken bone broth, butter, salt, garlic powder, dried oregano, dried thyme, and rosemary in a pot. Cook according to package instructions until the rice is tender. Set aside. Make High-Calorie Tzatziki: In a small bowl, mix store-bought tzatziki with full-fat Greek yogurt. Add salt and garlic powder to taste, stirring until smooth. Set aside. Shred & Thicken Chicken: Once the chicken is cooked, shred it directly in the slow cooker. Stir in the juice of one lemon and harissa paste, mixing well to combine. To thicken the sauce, mix 1 Tbsp cornstarch with 1 Tbsp cold water and stir into the chicken.","Assemble the Bowls: Divide the herby rice evenly among 10 bowls,(~14oz (400g)) Top each serving with harissa chicken and a dollop of tzatziki sauce. Sprinkle feta cheese over each bowl."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with extra feta, avocado, or a drizzle of olive oil for added calories and richness.', 38) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-buffalo-chicken-mac-n-cheese', 'Buffalo Chicken Mac n’ Cheese', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 650, 50, 68, 22, '["1000g (35oz) boneless, skinless chicken thighs (increased for more protein & calories)","100g buffalo sauce","30g (2 Tbsp) Worcestershire sauce","2 tsp garlic powder","2 tsp onion powder","5g (1 tsp) chicken bouillon","300g water","672g (24 oz) pasta of choice","700g (3 cups) whole milk cottage cheese","200g full-fat cream cheese","60g Parmigiano Reggiano","80g cheddar powder","150g buffalo sauce","80g (4 Tbsp) honey","400g whole milk","Salt and pepper, to taste"]'::jsonb, '["Make the Buffalo Chicken: Add chicken thighs to the slow cooker with buffalo sauce, Worcestershire sauce, garlic powder, onion powder, chicken bouillon, and water. Stir to coat the chicken evenly. Cover and cook on high for 2-3 hours or low for 3-4 hours until the chicken is tender and easily shredded.","Cook the Pasta: While the chicken cooks, bring a large pot of salted water to a boil. Add the pasta and cook for half the time listed on the package. Drain and set aside.","Prepare the Cheese Sauce: Blend the whole milk cottage cheese and grate the Parmigiano Reggiano. Combine & Cook: Once the chicken is done, shred it lightly in the slow cooker, and add the partially cooked pasta, cottage cheese, Parmigiano Reggiano, full-fat cream cheese, cheddar powder, extra buffalo sauce, honey, whole milk, salt, and pepper. Stir until everything is well combined, creating a creamy cheese sauce that coats the chicken and pasta.","Final Cooking: Cover and cook on high for an additional 15-20 minutes until the pasta is tender and the sauce thickens. If needed, add an extra 100-200g milk to adjust the sauce consistency. Portion & Store: Once done, divide the mixture into 10 servings (~14oz or 400g each) for easy meal prep. Allow the servings to cool completely before sealing and freezing for future meals."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with extra buffalo sauce, blue cheese crumbles, or a drizzle of ranch dressing for added richness.', 39) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chicken-enchilada-soup', 'Chicken Enchilada Soup', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 600, 48, 32, 30, '["Chicken","1340g (48oz) boneless, skinless chicken thighs","2 yellow onions, diced","3 jalapeño peppers, diced (remove seeds for less heat)","60g (4 Tbsp) butter (increased for richer flavor & calories)","6 cloves garlic, minced","60g (4 Tbsp) tomato paste","960g (4 cups) bone broth","480g (16oz) red enchilada sauce","794g (28oz) fire-roasted diced tomatoes","110g (4oz) green chiles","425g (15oz) black beans, drained & rinsed","425g (15oz) canned corn, drained","3 Tbsp hot sauce (optional, for spice boost)","50g (2 Tbsp) honey (slight increase for balance)","1 bunch cilantro stems, chopped","salt, chili powder, garlic powder, onion powder","2 tsp each: smoked paprika, cumin, oregano","1 tsp cayenne pepper","tsp cinnamon (amount unclear in the source)","400g full-fat Greek yogurt (replacing 0% Skyr for creaminess & calories)","200g (1 cup) full-fat cream cheese (swapped from 1/3 fat for added richness)","250g (2 cups) sharp cheddar cheese (boosted for extra cheesiness)"]'::jsonb, '["Saut the Aromatics: Heat a skillet over high heat. Add butter, onions, and jalapeños, cooking until they become soft and slightly charred. Reduce heat to medium and stir in garlic and tomato paste, cooking for an additional 5 minutes. Remove from heat.","Slow Cook the Base: Transfer the mixture to the slow cooker. Add chicken thighs, bone broth, enchilada sauce, fire-roasted tomatoes, green chiles, black beans, corn, hot sauce, honey, cilantro stems, and the chili spice blend. Stir everything to combine. Cover and cook on low for 4-5 hours or high for 3-4 hours.","Shred the Chicken: Once cooked, use tongs or forks to shred the chicken into large chunks and mix it back into the soup.","Melt the Cheese: Stir in cheddar cheese and cream cheese, mixing until fully melted and incorporated. Cover and let sit for 10-15 minutes.","Finish with Greek Yogurt: Add Greek yogurt and stir until smooth and creamy. Portion & Store: Divide into 10 servings (~16oz or 450g each). Garnish with fresh cilantro before serving. For meal prep, allow to cool before transferring to freezer-safe containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 3-4 minutes, stirring halfway through. Optional add-ins: Serve with crushed tortilla chips, avocado, or extra cheese for added texture.', 40) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-pasta-bolognese', 'Pasta Bolognese', 'meal', '', '["lunch","dinner"]'::jsonb, 12, 610, 45, 65, 22, '["Beef","1340g (48oz) 85% ground beef","6 slices thick-cut bacon","1580g (two","28oz cans) crushed tomatoes 2","dried oregano, salt 1","dried thyme, red pepper flakes, black pepper","tsp cayenne pepper (amount unclear in the source)","tsp nutmeg (amount unclear in the source)","672g (24oz) pasta of choice","60g (4 Tbsp) butter","3 onions, diced","12 garlic cloves, minced","90g (6 Tbsp) tomato paste","454g (16oz) beef bone broth","30g (2 Tbsp) Worcestershire sauce","15g (1 Tbsp) soy sauce Toppings","360g full-fat evaporated milk","150g Parmigiano Reggiano","50g (2 Tbsp) honey","4 dried bay leaves"]'::jsonb, '["Saut the Aromatics: In a large skillet over medium-high heat, cook the onions until translucent and beginning to brown. Stir occasionally to prevent sticking. Add butter, garlic, and tomato paste, stirring to combine. Lower the heat to medium and simmer for 7-8 minutes. Reduce & Intensify Flavor: Turn the heat to high and add beef bone broth, Worcestershire sauce, and soy sauce. Stir well, scraping the bottom of the skillet to deglaze any browned bits. Boil until the liquid is fully reduced to intensify the flavor. Slow Cook the Meat & Sauce: Transfer the mixture to the slow cooker. Add ground beef, crushed tomatoes, dried oregano, dried thyme, red pepper flakes, salt, pepper, cayenne, and nutmeg. Mix thoroughly. Top with bay leaves.","Add the Bacon: Dice the thick-cut bacon and line the edges of the slow cooker with it, or cook separately on the stove and add at the end for a crispy texture. Cover and slow cook on low for 5-6 hours or high for 3-4 hours.","Finish the Sauce: Once done, remove the bay leaves. Grate Parmigiano Reggiano and mix into the slow cooker along with full-fat evaporated milk and honey until smooth. Cover while preparing pasta.","Cook the Pasta: Bring a pot of salted water to a boil and cook the pasta halfway according to package instructions. Drain. Combine & Finish Cooking: Break up the meat in the slow cooker, then add the half- cooked pasta and stir well. Cover and cook on high for 20-30 minutes until the pasta is tender and the sauce thickens. Portion & Serve: Divide into 12 servings (~14oz or 400g each). Top with extra Parmigiano Reggiano before serving. For meal prep, allow to cool before storing in freezer-safe containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 3-4 minutes, stirring halfway through. Optional add-ins: Top with fresh basil, extra cheese, or drizzle of olive oil for more flavor.', 41) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-carnitas-inspired-pulled-pork-burritos', 'Carnitas-Inspired Pulled Pork Burritos', 'meal', '', '["lunch","dinner"]'::jsonb, 15, 590, 41, 60, 20, '["1790g (64 oz) pork shoulder","2 onions, diced","30g (2 Tbsp) oil of choice (increased for better browning & moisture)","2 Tbsp salt","1 Tbsp oregano","2 tsp black pepper","1 tsp cumin Juice from","2 oranges","6 garlic cloves, minced","tsp cinnamon (amount unclear in the source)","15g (1 Tbsp) apple cider vinegar","3 bay leaves","50g (2 Tbsp) honey","30g (2 Tbsp) butter","3 cloves garlic, minced","30g (2 Tbsp) tomato paste","1 tsp each: oregano, salt, pepper, onion powder","400g (2 cups) jasmine rice","900g (3 cups) chicken bone broth Burritos","15 burrito-sized tortillas","45g (3 Tbsp) full-fat Greek yogurt Cornstarch Slurry : 5g (1 tsp) cornstarch","1 tsp water"]'::jsonb, '["Saut the Onions: Dice the onions and cook in a large skillet over medium-high heat with oil until browned and caramelized, about 8-10 minutes, stirring occasionally.","Slow Cook the Pork: Cut the pork shoulder into 4-5 large chunks and place in the slow cooker. Add caramelized onions, salt, black pepper, oregano, cumin, cinnamon, garlic, honey, and apple cider vinegar. Squeeze the orange juice over the mixture, then place the orange peels on top. Add the bay leaves.","Cook the Pork: Cover and slow cook on high for 4-5 hours or low for 5-6 hours, until the pork is fork-tender. Once done, remove all liquid from the slow cooker and transfer it to a pan. Boil over medium-high heat for 10-15 minutes to reduce the sauce. If too thin, add a cornstarch slurry (1 tsp cornstarch mixed with 1 tsp water at a time) to thicken.","Shred the Pork: While the sauce reduces, shred the pork in the slow cooker. Once the sauce is thickened, pour it back over the shredded pork and mix well.","Prepare the Spanish Rice: Melt butter in a medium pot over medium heat. Add minced garlic and tomato paste and saut for 3-5 minutes. Stir in jasmine rice, chicken bone broth, oregano, salt, pepper, and onion powder. Bring to a boil, then reduce heat to low and cover for 20-25 minutes. Fluff once done.","Assemble the Burritos: Divide the pork and rice evenly approximately 196.8 grams (6.94 ounces) 15 tortillas. Top with full-fat Greek yogurt before rolling. Store & Freeze: Wrap each burrito tightly in foil and store in the freezer for meal prep."]'::jsonb, 'For meal prep: Store in freezer-safe foil wraps for up to 3 months. Reheating: Microwave for 2-3 minutes wrapped in a damp paper towel or toast in a skillet for a crispy finish. Optional add-ins: Serve with queso, guacamole, or fresh salsa for even more calories & flavor.', 42) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-thai-red-curry-peanut-chicken-bowls', 'Thai Red Curry Peanut Chicken Bowls', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 675, 52, 70, 20, '["1790g (64oz) boneless, skinless chicken thighs","180g peanut butter","120g Thai red curry paste","40g (2 Tbsp) soy sauce","40g (2 Tbsp) fish sauce","80g (4 Tbsp) honey","20g (1 Tbsp) grated ginger","20g (1 Tbsp) grated garlic Juice + zest of","1 lime","240g coconut cream","Juice of 1-2 limes","Chopped Thai basil","750g (3 cups) short-grain rice","1300g (5 cups) chicken bone broth"]'::jsonb, '["Make the Sauce: Grate the ginger and garlic. In a bowl, whisk together peanut butter, Thai red curry paste, soy sauce, fish sauce, honey, lime juice, zest, and coconut cream until smooth. Divide the sauce in half.","Slow Cook the Chicken: Place chicken thighs in a slow cooker and pour half the sauce over them. Mix to coat evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours, until tender.","Cook the Rice: Combine short-grain rice and chicken bone broth in a pot, bring to a boil, reduce heat to low, cover, and simmer for 20-25 minutes or until the liquid is absorbed. Let sit covered for 5 minutes, then fluff with a fork.","Finish the Chicken: Once the chicken is done, shred lightly and add the remaining sauce along with the juice of 1-2 limes (to taste). Stir well, add chopped Thai basil, and let sit for 5-10 minutes to absorb the flavors. Assemble & Store: Spoon rice into bowls or containers, and top with the chicken. Divide into 10 servings (~15oz or 425g each). Store leftovers in freezer-safe containers for meal prep."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with crushed peanuts, extra Thai basil, or a drizzle of coconut cream for added texture and flavor.', 43) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-chicken-parmesan-pasta', 'Chicken Parmesan Pasta', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 620, 51, 70, 16, '["Chicken","1120g (40oz) chicken breast","794g (28oz) can of peeled or crushed tomatoes","2 Tbsp tomato paste","2 Tbsp minced garlic 1.5 Tbsp coarse salt","1 Tbsp Italian seasoning","1 tsp black pepper","1 tsp onion powder","1 tsp chili flakes","30g (2 Tbsp)","750g (26oz) pasta of choice","400g full-fat cottage cheese (switched from 2% to full-fat for more calories)","300g whole milk (switched from fat-free for extra creaminess)","150g full-fat cream cheese","180g Parmigiano Reggiano (boosted for extra flavor and calories)","1 Tbsp white miso","Salt & pepper, to taste","Chopped fresh basil"]'::jsonb, '["Prepare the Chicken & Tomato Sauce: Dice the chicken breasts and add them to the slow cooker. Grate the Parmigiano Reggiano and add to the slow cooker along with the canned tomatoes, tomato paste, minced garlic, salt, Italian seasoning, black pepper, onion powder, and chili flakes. Stir well to combine. Cover and cook on high for 2-3 hours or low for 3-4 hours until the chicken is tender.","Shred the Chicken: Once the chicken is cooked, shred it directly in the slow cooker using two forks, mixing it back into the sauce.","Cook the Pasta: Bring a pot of salted water to a boil and cook the pasta for half the time listed on the package. Drain and add to the slow cooker.","Make the Cheese Sauce: Freshly grate the Parmigiano Reggiano and blend with full-fat cottage cheese, whole milk, full-fat cream cheese, and white miso (optional). Add salt and pepper to taste and blend until smooth. Combine & Cook: Pour the cheese sauce into the slow cooker and mix well to coat the shredded chicken and pasta with the sauce. Cover and cook on low for 15- 20 minutes until the pasta is tender and fully cooked. Portion & Store: Once done, stir everything one final time and chop fresh basil as a topping. Divide into 10 portions (~15oz or 425g each). Let leftovers cool before transferring to freezer-safe containers."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Add fresh mozzarella or burrata on top before serving for extra richness.', 44) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-street-taco-chicken-chipotle-lime-rice', 'Street Taco Chicken & Chipotle Lime Rice', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 610, 51, 70, 12, '["Chicken","1790g (64oz) boneless, skinless chicken thighs","160g orange juice","Juice of","3 limes","45g (3 Tbsp) soy sauce","30g (2 Tbsp) minced garlic","2 Tbsp salt","5 tsp cumin","1 Tbsp onion powder","1 Tbsp garlic powder","1 Tbsp chili powder","2 tsp black pepper","2 tsp dried oregano","60g (3 Tbsp) honey","640g (3 cups) jasmine rice","1300g (5 cups) bone broth","3 chipotle peppers","30g (2 Tbsp) tomato paste","30g (2 Tbsp) olive oil","Juice of","1 lime","Splash of bone broth","Garlic powder, salt, onion powder, cumin Garnish","1 bunch cilantro, chopped","Juice of","2 limes","2 white onions, diced","2 avocados, diced"]'::jsonb, '["Marinate the Chicken: Mince the garlic and mix in a large bowl with orange juice, lime juice, soy sauce, salt, cumin, onion powder, garlic powder, chili powder, black pepper, dried oregano, and honey until well combined.","Slow Cook the Chicken: Add chicken thighs to the slow cooker and pour the marinade over them, stirring to coat evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours until tender. Shred & Garnish: Once the chicken is cooked, shred lightly with two forks, leaving some chunks intact. Stir in raw diced white onions, chopped cilantro, and the juice of 2 limes for extra flavor.","Make the Chipotle Rice: Blend chipotle peppers, tomato paste, olive oil, lime juice, and bone broth until smooth. Adjust seasoning with garlic powder, salt, onion powder, and cumin to taste.","Cook the Rice: Combine rice and blended mixture in a pot. Bring to a boil, reduce to low heat, cover, and simmer for 20-25 minutes until the liquid is absorbed. Let sit for 5-10 minutes off heat, then fluff with a fork. Portion & Serve: Divide the chipotle red rice into 10 equal servings, each 15oz (425g). Top each with shredded street taco chicken and diced avocado (if using). Store leftovers in freezer-safe containers for meal prep."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with queso fresco, sour cream, or extra avocado for a richer texture.', 45) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-cheesy-chili-crisp-miso-orzo', 'Cheesy Chili Crisp Miso Orzo', 'meal', '', '["lunch","dinner"]'::jsonb, 10, 610, 48, 68, 17, '["Chicken","1340g (48oz) boneless, skinless chicken thighs","60g (4 Tbsp) white miso paste","50g (3 Tbsp) chili crisp","50g (2 Tbsp) honey","30g (2 Tbsp) mirin","1 Tbsp garlic powder Black pepper, to taste","1 white onion, diced","500g (2 cups) whole milk","80g (5 Tbsp) white miso paste","Juice of","1 lemon","250g (2 cups) mozzarella","672g (24 oz) orzo pasta Toppings","White/black sesame seeds, to taste","2 bundles green onions, chopped"]'::jsonb, '["Marinate the Chicken: In a large bowl, whisk together white miso paste, chili crisp, honey, mirin, garlic powder, and black pepper until well combined. Add chicken thighs to the slow cooker and pour the miso sauce over them, stirring to coat evenly. Cover and cook on high for 3-4 hours or low for 4-5 hours, until tender.","Cook the Orzo: Bring a large pot of salted water to a boil. Add orzo pasta and cook for half the time listed on the package. Drain and set aside.","Prepare the Miso Milk: In a blender, combine whole milk and white miso paste. Blend until smooth and creamy.","Saut the Onion: Heat a pan over medium heat and cook the diced white onion until softened and lightly browned.","Combine Everything: Once the chicken is done, lightly shred it in the slow cooker, leaving some larger pieces intact for texture. Stir in the cooked onion, half- cooked orzo, miso milk, lemon juice, and shredded mozzarella. Add a pinch of salt. Cover and cook on low for 20-30 minutes until the sauce thickens and the pasta is fully cooked. Garnish & Serve: Chop the green onions and sprinkle them on top. Add white/black sesame seeds to taste. Divide into 10 servings (~14oz or 400g each). Store leftovers in freezer-safe containers for meal prep."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Top with extra chili crisp, crispy fried onions, or shredded nori for added crunch.', 46) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-korean-beef-noodles', 'Korean Beef Noodles', 'meal', '', '["lunch","dinner"]'::jsonb, 7, 650, 47, 75, 19, '["Beef","900g (32oz) 85% ground beef","65g (4 Tbsp) gochujang","50g (3 Tbsp) soy sauce","45g (3 Tbsp) regular ketchup (no sugar-free substitutesfull flavor & calories!)","1 Tbsp garlic powder","15g (1 Tbsp) rice wine vinegar","Salt and black pepper, to taste White parts of","3 green onions","80g (4 Tbsp) honey","25g (1 Tbsp) sesame oil","300g water","90g full-fat mayo","50g (2 Tbsp) gochujang","20g (1 Tbsp) sriracha","15g (1 Tbsp) yuzu ponzu","15g (1 Tbsp) sesame oil","5 packets Momofuku Sweet & Spicy noodles OR 45g (3 Tbsp) Korean BBQ marinade of choice with","600g (21 oz) fresh noodles"]'::jsonb, '["Slow Cook the Beef: In the slow cooker, mix together ground beef, gochujang, soy sauce, ketchup, garlic powder, rice wine vinegar, salt, black pepper, and green onion whites. Cover and cook on low for 3-4 hours until tender.","Make Spicy Mayo: In a bowl, whisk together full-fat mayo, gochujang, sriracha, yuzu ponzu, and sesame oil. Cover and refrigerate until ready to serve.","Prepare the Noodles: Cook the noodles according to package instructions. Drain and set aside. Combine & Finish: Once the beef is done, add the cooked noodles, water, honey, sesame oil, and Momofuku flavor packets (or Korean BBQ marinade). Stir everything together until the noodles absorb the sauce. Cover and let sit for 10-15 minutes to meld flavors. Serve & Store: Divide into 7 portions (~15oz or 425g each). Drizzle with spicy mayo and garnish with chopped green onions. Store leftovers in freezer-safe containers for meal prep."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 2-3 minutes, stirring halfway through. Optional add-ins: Serve with soft-boiled eggs, kimchi, crushed peanuts, or extra sesame seeds for more texture.', 47) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-red-enchilada-chicken-soup', 'Red Enchilada Chicken Soup', 'meal', '', '["lunch","dinner"]'::jsonb, 8, 580, 62, 24, 21, '["Chicken","1790g (64oz) boneless, skinless chicken thighs","480g (2 cups) red enchilada sauce","7oz can chipotle peppers in adobo","1 large white onion, diced","Juice of","1 lime","1 Tbsp salt","1 Tbsp garlic powder","Dash of black pepper","80g (4 Tbsp) honey","150g (1 cup) full-fat feta cheese","475g (2 cups) full-fat Greek yogurt","360g Whole Milk","1 bunch chopped cilantro"]'::jsonb, '["Slow Cook the Chicken: Add chicken thighs, diced onion, red enchilada sauce, chipotle peppers, lime juice, salt, garlic powder, and black pepper to the slow cooker. Stir well to coat the chicken evenly. Cover and cook on high for 2-3 hours or low for 3-4 hours, until the chicken is tender. Shred & Blend: Once the chicken is cooked, shred it directly in the slow cooker with two forks. Mix well so the flavors fully absorb. Stir in feta cheese and honey, cover, and cook on high for an additional 15 minutes to allow the feta to soften and integrate.","Make It Creamy: Turn off the heat and let the mixture cool for 10 minutes before adding dairy. Gradually stir in heavy cream, mixing well to maintain smooth consistency. Once combined, fold in full-fat Greek yogurt and chopped cilantro until creamy and fully incorporated. Serve & Store: Divide into 8 servings (~16oz or 450g each). Allow to cool completely before freezing in airtight containers for meal prep."]'::jsonb, 'For meal prep: Store in freezer-safe containers for up to 3 months. Reheating: Microwave for 3-4 minutes, stirring halfway through. Optional add-ins: Serve with crushed tortilla chips, avocado slices, extra feta, or a drizzle of hot sauce for added flavor.', 48) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-crockpot-breakfast-casserole', 'Crockpot Breakfast Casserole', 'meal', '', '["breakfast"]'::jsonb, 8, 640, 42, 50, 35, '["32 oz frozen diced hash browns","1 lb (16oz) thick-cut bacon, cooked & crumbled","6 oz breakfast sausage, cooked & crumbled","2 cups (8oz) sharp cheddar cheese, shredded","cup (2oz) mozzarella cheese (amount unclear in the source)","2 green onions, sliced","1 small white onion, finely diced","1 red bell pepper, diced","12 whole eggs","1 cups (10oz) heavy cream (amount unclear in the source)","1 tsp dry mustard powder","1 tsp salt","1 tsp garlic powder","tsp black pepper (amount unclear in the source)"]'::jsonb, '["Prep the Protein & Veggies: Cook the bacon and sausage until crispy, then drain excess fat, leaving ~1 Tbsp in the pan. If desired, saut the white onion in bacon grease for 3-5 minutes to soften its flavor.","Layer the Casserole: Grease a 6qt slow cooker. Layer half the hash browns, meat, onions, peppers, and cheese. Repeat layers, ending with cheese. Do not stir.","Mix the Egg Mixture: In a bowl, whisk together eggs, heavy cream, mustard powder, salt, garlic powder, and black pepper. Pour the egg mixture over the layers in the slow cooker.","Slow Cook It: Low: 7-8 hours overnight High: 3-4 hours for quicker cooking Once cooked, uncover and let rest for 15 minutes before serving."]'::jsonb, 'Storage: Cool completely and store in airtight containers in the fridge for up to 5 days or freeze for up to 3 months. Reheating: Microwave for 1-2 minutes or bake at 375F for 10 minutes. Extra Toppings: Add avocado slices, hot sauce, or sour cream for even more calories.', 49) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
INSERT INTO recipes (id, title, kind, blurb, meals, servings, calories, protein_g, carbs_g, fat_g, ingredients, steps, notes, position) VALUES ('cook-hearty-slow-cooker-breakfast-hash', 'Hearty Slow-Cooker Breakfast Hash', 'meal', '', '["breakfast"]'::jsonb, 8, 620, 28, 68, 32, '["20 fully cooked breakfast sausage links","8 cups diced red potatoes","6 medium carrots, diced","4 green onions, thinly sliced (white and pale green parts only)","4 Tbsp extra virgin olive oil","2 Tbsp red wine vinegar","2 Tbsp fresh dill, divided","2 tsp kosher salt","1 tsp coarsely ground black pepper, divided","tsp crushed red pepper flakes (amount unclear in the source)","4 Tbsp crumbled feta cheese Eggs","2 Tbsp butter (for frying eggs, more richness!)","8 large eggs","4 Tbsp maple syrup"]'::jsonb, '["Cook the Sausage: In a large skillet over medium heat, cook breakfast sausage links, turning occasionally, until browned and heated through, about 8-9 minutes.","Prepare the Hash Base: In a 6-qt slow cooker, combine diced red potatoes, carrots, green onions, olive oil, red wine vinegar, 1 Tbsp dill, 1 tsp kosher salt, tsp black pepper, and crushed red pepper flakes. Arrange cooked sausage links on top of the vegetable mixture. Cover and cook on low for 5-6 hours, until vegetables are fork- tender.","Final Steps: Transfer vegetables to a serving platter, sprinkle with feta cheese, and top with sausage.","Cook the Eggs: Heat butter in a large skillet over medium heat. Crack 8 eggs into the pan and cook to your desired doneness. Assemble & Serve: Place cooked eggs on top of the hash and sausages. Sprinkle with remaining fresh dill and black pepper. Drizzle with maple syrup for a perfect sweet-savory balance!"]'::jsonb, 'Meal Prep: Cool completely and store in airtight containers in the fridge for up to 5 days or freeze for up to 3 months. Reheating: Microwave for 1-2 minutes, adding a splash of water to keep moisture. Extra Toppings: Try avocado slices, hot sauce, or a sprinkle of shredded cheddar for more calories!', 50) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, blurb = EXCLUDED.blurb, meals = EXCLUDED.meals, servings = EXCLUDED.servings, calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, ingredients = EXCLUDED.ingredients, steps = EXCLUDED.steps, notes = EXCLUDED.notes WHERE recipes.updated_at = recipes.created_at;
